import{c as o,o as r,b as p}from"./index-D22dK0d7.js";const s="/docs/progrev_temp_block.png",e="/docs/progrev_perm_block.png",i={class:"markdown-body"},c={__name:"Прогрев аккаунтов и блокировка WhatsApp, Telegram",setup(g,{expose:l}){return l({frontmatter:{}}),(a,t)=>(r(),o("div",i,[...t[0]||(t[0]=[p('<p>Подключаемый к сервисам аккаунт WhatsApp* должен быть создан не менее <strong>7 дней</strong> перед подключением, Telegram — не менее <strong>14 дней</strong>. Аккаунт должен быть «прогрет» во избежание блокировки со стороны мессенджеров.</p><blockquote><p>После первой временной блокировки аккаунт попадает в <strong>14-дневный «период наблюдения»</strong>. В течение этого времени важно снизить активность — минимум 7 дней (оптимально 14 дней) избегать автоматизации, спама или интенсивного использования, при этом прогревая аккаунт по инструкции ниже — это снимет ограничения и убережёт от повторной блокировки.</p></blockquote><h2>Что важно для мессенджеров</h2><ul><li>С какого аккаунта делается рассылка (как давно зарегистрирован, обычная активность и т.д.);</li><li>Текст сообщения для отправки (одинаковый текст или используются переменные);</li><li>Получатель сообщения (холодная, тёплая или горячая база);</li><li>Реакция на сообщения (жалобы получателей на спам, ответ на сообщения, реакции и т.д.).</li></ul><p>Свежие аккаунты (регистрация в мессенджере до 14 дней) могут быть быстро заблокированы, если осуществлять с них рассылку — для мессенджеров отправка более 2 одинаковых сообщений одномоментно воспринимается как спам.</p><p>Чем больше доверия к аккаунту со стороны WhatsApp*/Telegram, тем больше с него можно разослать сообщений. Доверие появляется от комбинации обычных действий и возраста аккаунта:</p><ul><li>Появление онлайн;</li><li>Переписки в диалогах (предпочтительнее с контактами из телефонной книжки);</li><li>Звонки аудио и видео;</li><li>Вступление в группы/чаты и переписка в них;</li><li>Проставление статусов (WhatsApp*) или постинг сторис (Telegram Premium) и т.д.</li></ul><blockquote><p>При прогреве аккаунта сразу после регистрации не нужно делать много активностей: много переписываться, вступать в большое количество групп/чатов, совершать много звонков и т.д. Также желательно вести переписку со свежего аккаунта не с другим свежим аккаунтом.</p></blockquote><h2>Подходы к прогреву аккаунтов</h2><ol><li>Переписка свежего аккаунта с прогретыми аккаунтами — 3–10 сообщений в диалоге раз в 3–8 часов.</li><li>Появление онлайн на 1–3 минуты, как с открытым мессенджером на устройстве, так и со свёрнутым.</li><li>Открывать непрочитанные диалоги, делать случайные клики.</li><li>Вступать в 1–3 группы/чата раз в 1–2 дня, писать туда сообщения (можно просто при вступлении).</li><li>Звонки по 20–40 сек контактам из телефонной книги 1–2 раза в день.</li><li>Сделать так, чтобы на аккаунт писали другие люди, и отвечать на сообщения (автоответчик или вручную).</li></ol><p>Лучше всего начинать прогрев с появления онлайн (1–3 дня) на пару минут в день, затем начать вести переписку с давно зарегистрированным аккаунтом в мессенджере, совершать звонки и т.д.</p><hr><h2>Что делать, если заблокировали WhatsApp*</h2><p>Когда номер заблокирован, смена SIM-карты или устройства не поможет — как только вы установите WhatsApp* и подключитесь к интернету, сервер отправит сигнал, который автоматически заблокирует аккаунт снова.</p><p><strong>Ключевые моменты о блокировках</strong></p><p>Было: аккаунт мог пережить до 4 временных приостановок, а 5-я приводила к постоянной блокировке. Стало: после <strong>3 временных блокировок</strong> аккаунт блокируется на <strong>1–2 месяца</strong>.</p><p><strong>Если ограничения временные</strong> (см. скриншот ниже) — никаких действий предпринимать не нужно. Ограничения будут сняты автоматически по прошествии указанного срока, и вы получите об этом уведомление в WhatsApp*. Можно попробовать уменьшить срок ограничений, написав в поддержку — нажмите на текст <strong>«Свяжитесь с нами»</strong>.</p><p><img src="'+s+'" alt="Временные ограничения на аккаунт WhatsApp — кнопка «Свяжитесь с нами»"></p><p><strong>Если на аккаунт наложена постоянная блокировка</strong> (см. скриншот ниже) — нажмите на кнопку <strong>«Запросить рассмотрение»</strong>.</p><p><img src="'+e+'" alt="Постоянная блокировка аккаунта WhatsApp — кнопка «Запросить рассмотрение»"></p><hr><h2>Что делать, если заблокировали Telegram</h2><p>Если бан временный, то при первом нарушении необходимо ждать <strong>24 часа</strong> до разблокировки.</p><p><strong>Как снять бан.</strong> Текст обращения можно писать на любом языке, но лучше по-английски — так больше шанс, что вам ответят.</p><ol><li><p><strong>Через @SpamBot:</strong></p><ul><li>В Telegram найдите и откройте диалог с <strong>@SpamBot</strong>;</li><li>Нажмите <strong>/start</strong> → «Я не могу писать не контактам» → «Это ошибка»;</li><li>Отправьте шаблон на английском:</li></ul><blockquote><p>Telegram developers, I have not violated the rules. Please remove restrictions</p></blockquote></li><li><p><strong>Письмо в поддержку:</strong></p><ul><li>Напишите письмо на электронную почту <strong><a href="mailto:spam@telegram.org">spam@telegram.org</a></strong>;</li><li>Тема письма: <code>Unban request for [ваш номер]</code>;</li><li>В тексте укажите номер, опишите ситуацию, приложите скриншоты переписок. Ответ приходит в течение нескольких дней.</li></ul></li><li><p><strong>Восстановление через форму обратной связи:</strong></p><ul><li>Заполните форму обратной связи на <a href="https://telegram.org/support">telegram.org/support</a>;</li><li>Опишите в ней проблему, укажите адрес электронной почты и телефон. Ответ приходит через 1–5 дней.</li></ul></li></ol><hr><p><em>* Принадлежит компании Meta, которая признана экстремистской организацией и запрещена на территории РФ.</em></p>',27)])]))}};export{c as default};
